const params=new URLSearchParams(location.search),requested=params.get('species')||'pineapple',theme=params.get('theme')==='stress'?'stress':'development';
const root=document.querySelector('#omicsContent'),back=document.querySelector('#speciesBack');back.href=`species.html?species=${encodeURIComponent(requested)}`;
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const recordLinks=record=>{const links=[];if(record.url)links.push(`<a href="${esc(record.url)}" target="_blank" rel="noopener noreferrer">NCBI genome record</a>`);if(/^PRJ[A-Z]+\d+$/i.test(record.bioproject||''))links.push(`<a href="https://www.ncbi.nlm.nih.gov/bioproject/${encodeURIComponent(record.bioproject)}" target="_blank" rel="noopener noreferrer">BioProject ${esc(record.bioproject)}</a>`);return links.length?`<div class="record-links">${links.join('')}</div>`:''};
function englishContext(value){return String(value||'').replaceAll('果实','fruit').replaceAll('花/开花','flower/flowering').replaceAll('胚/胚发生','embryo/embryogenesis').replaceAll('芽/茎尖','bud/shoot apex').replaceAll('分生组织','meristem').replaceAll('中果皮','mesocarp').replaceAll('果皮','peel').replaceAll('果肉','pulp').replaceAll('种子','seed').replaceAll('发育','development').replaceAll('时期','developmental stage').replaceAll('低温','low temperature').replaceAll('病原/感染','pathogen/infection').replaceAll('病毒','virus').replaceAll('病害','disease').replaceAll('叶','leaf').replaceAll('根','root').replaceAll('茎','stem').replaceAll('花','flower').replaceAll('、',', ')}
const stressNames=/stress|disease|pathogen|infection|abiotic|biotic/i;
function shortReadRecords(transcriptome){if(!transcriptome)return[];return transcriptome.categories.filter(category=>theme==='stress'?stressNames.test(category.name):!stressNames.test(category.name)).map(category=>({theme,omicsType:'RNA-seq transcriptome',bioproject:'Curated RNA-seq collection',title:category.name,platform:transcriptome.layout,context:category.name,runs:category.runs,status:'Integrated research accessions'}))}
Promise.all([fetch('data/genomes.json').then(r=>r.json()),fetch('data/transcriptomes.json').then(r=>r.json()),fetch('data/advanced-omics.json').then(r=>r.json())]).then(([genomes,transcriptomes,advanced])=>{
  const species=genomes.species.find(item=>item.key===requested)||genomes.species[0],transcriptome=transcriptomes.species.find(item=>item.scientificName===species.scientificName||item.commonName.toLowerCase()===species.commonName.toLowerCase());
  let records=[...(advanced.species[species.key]||[]).filter(record=>record.theme===theme),...shortReadRecords(transcriptome)];
  if(theme==='development')records.unshift(...species.assemblies.map(assembly=>({theme,omicsType:'Genome assembly',bioproject:assembly.bioproject,title:assembly.assemblyName,platform:assembly.level,context:assembly.cultivar?.replace('cultivar=','')||'Reference assembly',runs:[],status:assembly.accession,url:assembly.ncbiUrl})));
  const groups=advanced.sequencingTypes.concat(['Genome assembly','RNA-seq transcriptome']).filter((type,index,array)=>array.indexOf(type)===index).map(type=>({type,records:records.filter(record=>record.omicsType===type)})).filter(group=>group.records.length);
  document.title=`${species.commonName} ${theme==='stress'?'Stress Response':'Growth & Development'} | TropicalfruitLLM 1.0`;
  root.innerHTML=`<section class="omics-heading"><small>${esc(species.scientificName)}</small><h1>${esc(species.commonName)}</h1><h2>${theme==='stress'?'Stress Response':'Growth & Development'}</h2><p>Sequencing evidence is grouped by omics type. Where a public accession is available, the original repository record is linked directly.</p></section><section class="omics-type-list">${groups.length?groups.map(group=>`<article class="omics-type"><header><span>OMICS LAYER</span><h3>${esc(group.type)}</h3></header><div class="omics-records">${group.records.map(record=>`<div class="omics-record"><div><small>${esc(record.status||record.bioproject||'Integrated project')}</small><h4>${esc(record.title||group.type)}</h4><p>${esc(record.platform||'Integrated platform')}${record.context?` · ${esc(englishContext(record.context))}`:''}</p>${recordLinks(record)}</div>${record.runs?.length?`<div class="tag-list">${record.runs.map(run=>`<span>${esc(run)}</span>`).join('')}</div>`:'<div class="tag-list"><span>Integrated record</span></div>'}</div>`).join('')}</div></article>`).join(''):'<article class="empty-omics"><h3>No curated records in this theme</h3><p>This species remains available in the database and can be expanded as new evidence is integrated.</p></article>'}</section>`;
}).catch(()=>{root.innerHTML='<p class="loading">Omics data are temporarily unavailable.</p>'});
